import os,json,stat,subprocess,time,re
from pathlib import Path
R=Path('/srv/projects/skill-universal')
P={
'root_ferrari_legacy':Path('/root/.local/share/motor-ferrari'),
'ferrari_skill_results':R/'.runtime/skill-results',
'ferrari_skill_requests':R/'.runtime/skill-requests',
'ferrari_private_npm':R/'.runtime/npm',
'ferrari_private_venv':R/'.runtime/venv',
'codex_broken_home':Path('/home/ubuntu/codex-agent'),
'codex_bridge_home':Path('/home/ubuntu/codex-bridge'),
'srv_lowcost_alias':Path('/srv/lowcost-europa'),
'srv_pink_alias':Path('/srv/pink-iptv'),
'ubuntu_android_empty':Path('/home/ubuntu/.android'),
'ubuntu_codex_test_empty':Path('/home/ubuntu/codex-tests'),
}
def du(p,t=45):
 try:
  x=subprocess.run(['du','-sx','-B1',str(p)],capture_output=True,text=True,timeout=t)
  return int(x.stdout.split()[0]) if x.returncode==0 else None
 except Exception:return None
out={'mode':'READ_ONLY','timestamp':time.time(),'targets':{},'candidate_lists':{},'project_root_unchanged':R.is_dir() and not R.is_symlink()}
for label,p in P.items():
 d={'exists':p.exists(),'symlink':p.is_symlink()}
 if p.is_symlink():
  try:d['resolved']=str(p.resolve(strict=True))
  except OSError:d['broken']=True
 if p.exists() and not p.is_symlink():
  d['uid']=p.stat().st_uid;d['kind']='directory' if p.is_dir() else 'file'
  d['allocated_bytes_du']=du(p)
  if p.is_dir():
   arr=list(p.iterdir())
   d['entries']=len(arr)
   if label=='root_ferrari_legacy':
    d['children']=[{'name':x.name,'is_symlink':x.is_symlink(),'directory':x.is_dir(),'uid':x.lstat().st_uid,'du_bytes':du(x)} for x in arr[:20]]
    for x in arr:
     if x.is_dir() and not x.is_symlink():
      d['grandchildren']=[{'name':y.name,'is_symlink':y.is_symlink(),'directory':y.is_dir(),'du_bytes':du(y)} for y in list(x.iterdir())[:30]]
   if label in ('ferrari_skill_results','ferrari_skill_requests'):
    dirs=[]
    for x in arr:
     if x.is_symlink():continue
     try:st=x.stat()
     except OSError:continue
     if label=='ferrari_skill_requests' and (not re.fullmatch(r'request-\d+\.json',x.name) or not x.is_file()):continue
     if label=='ferrari_skill_results' and (not re.fullmatch(r'\d+',x.name) or not x.is_dir()):continue
     dirs.append((x.name,int(time.time()-st.st_mtime)))
    d['known_generated_entries']=len(dirs)
    d['older_2d']=sum(y>172800 for _,y in dirs)
    d['older_1d']=sum(y>86400 for _,y in dirs)
    d['older_12h']=sum(y>43200 for _,y in dirs)
    d['latest_6_names']=[n for n,_ in sorted(dirs,key=lambda z:z[1])[:6]]
 out['targets'][label]=d
# Exclude auditor's process ancestry when measuring other processes relying on old paths.
ignored={os.getpid()};pid=os.getppid()
while pid>1:
 ignored.add(pid)
 try:
  m=re.search(r'(?m)^PPid:\s*(\d+)$',(Path('/proc')/str(pid)/'status').read_text())
  pid=int(m.group(1)) if m else 0
 except (OSError,ValueError):break
links=['root_ferrari_legacy','codex_broken_home','codex_bridge_home','srv_lowcost_alias','srv_pink_alias']
for label in links:
 p=P[label];hits=[]
 for proc in Path('/proc').iterdir():
  if not proc.name.isdecimal() or int(proc.name) in ignored:continue
  try:
   a=(proc/'cmdline').read_bytes()
   cwd=os.readlink(proc/'cwd')
   name=(proc/'comm').read_text().strip()[:40]
  except OSError:continue
  needle=os.fsencode(str(p))
  if needle in a or cwd.startswith(str(p)+'/'):
   if len(hits)<20:hits.append(name)
 out['candidate_lists'][label]={'other_process_count_limited':len(hits),'process_names':hits[:10]}
print(json.dumps(out,sort_keys=True))
